fn intersperse(numbers: &[i32], delim: i32) -> Vec<i32> {
    let n = numbers.len();
    if n == 0 {
        return Vec::new();
    }

    // Reserve exactly 2*n - 1 slots: n numbers and (n-1) delimiters
    let mut res = Vec::with_capacity(2 * n - 1);

    // Push the first element, then for each subsequent element push delim, then the element.
    let mut iter = numbers.iter();
    if let Some(&first) = iter.next() {
        res.push(first);
    }
    for &num in iter {
        res.push(delim);
        res.push(num);
    }

    res
}

